import React, { useState, useEffect, useLayoutEffect, useRef } from 'react';
import gsap from 'gsap';

import ohpi from '../../assets/images/ohpi.jpg';
import message from '../../assets/images/messaging.jpg';
import inventory from '../../assets/images/ictinvent.png';
import news from '../../assets/images/news.jpg';
import ohpiVideo from '../../assets/videos/orient.mp4';
import messageVideo from '../../assets/videos/messaging.mp4';
import inventoryVideo from '../../assets/videos/inventory.mp4';
import cybernews from '../../assets/videos/cybernews.mp4';

const projects = [
  {
    title: 'Orient Holdings',
    image: ohpi,
    url: 'https://github.com/BixbyNX/ohpi',
    description: 'A company profile website showcasing services and portfolio. Developed and deployed a responsive company website featuring a modern, clean design with engaging user experiences across various devices using Bootstrap, HTML, CSS, and JavaScript',
  },
  {
    title: 'Messaging',
    image: message,
    url: 'https://github.com/BixbyNX/Engkreptukv2',
    description: 'Designed and developed a secure messaging application using the .NET Framework with C#, featuring end-to-end encryption, message transmission, user authentication, and real-time updates.',
  },
  {
    title: 'Inventory',
    image: inventory,
    url: 'https://github.com/BixbyNX/ICT-inventory',
    description: 'Inventory management system with tracking features. Developed a web-based inventory management system using PHP (Laravel) and Vue.js, implementing full CRUD functionality to efficiently track, manage, and update stock levels.',
  },
  {
    title: 'Cyber News',
    image: news,
    url: 'https://github.com/BixbyNX/cybernews',
    description: 'Cybersecurity news dissemination system for daily threat intelligence. Developed using Laravel and Vue.js, the platform features a full CRUD system for administrators to manage updates with support for file attachments and external links, while implementing a draft/published status workflow for precise content control.',
  },
];

const projectVideos = {
  'Orient Holdings': ohpiVideo,
  'Messaging': messageVideo,
  'Inventory': inventoryVideo,
  'Cyber News': cybernews,
};

const ProjectsPopup = ({ onClose }) => {
  const [activeProject, setActiveProject] = useState(null);
  const [clickedProject, setClickedProject] = useState(null);
  const [hoveredIndex, setHoveredIndex] = useState(null);
  const [isAnimating, setIsAnimating] = useState(true);
  const [isVideo, setIsVideo] = useState(false);

  const containerRef = useRef(null);
  const closeBtnRef = useRef(null);
  const titleRefs = useRef([]);
  const imageRef = useRef(null);
  const videoRef = useRef(null);
  const wasClicked = useRef(false);
  const displayedProject = clickedProject || activeProject;

  // 1. Initial entrance animation
  useEffect(() => {
    const validTitles = titleRefs.current.filter(Boolean);
    let ctx = gsap.context(() => {
      gsap.set(validTitles, { x: 100, autoAlpha: 0 });
      gsap.set(closeBtnRef.current, { autoAlpha: 0 });

      const tl = gsap.timeline();
      tl.to(validTitles, {
        x: 0,
        autoAlpha: 1,
        duration: 1,
        stagger: 0.15,
        ease: 'power3.out',
        delay: 0.2,
        onComplete: () => setIsAnimating(false),
      }).to(closeBtnRef.current, { autoAlpha: 1, duration: 0.5 }, "-=0.5");
    }, containerRef);
    return () => ctx.revert();
  }, []);

  useEffect(() => {
    if (isAnimating) return;
    const validTitles = titleRefs.current.filter(Boolean);

    let ctx = gsap.context(() => {
      validTitles.forEach((el, i) => {
        const isClicked = clickedProject && projects[i].title === clickedProject.title;
        const isHovered = hoveredIndex === i;

        if (clickedProject) {
          if (isClicked) {
            const vh = window.innerHeight;
            const rect = el.getBoundingClientRect();
            gsap.to(el, {
              y: (vh * 0.7) - rect.top,
              x: 0,
              scale: 1.5,
              autoAlpha: 1,
              duration: 0.8,
              ease: 'power3.out',
            });
          } else {
            gsap.to(el, { autoAlpha: 0, scale: 0.8, x: 50, duration: 0.4 });
          }
        } else {
          let targetScale = 1;
          let targetAlpha = 1;

          if (hoveredIndex !== null) {
            if (isHovered) {
              targetScale = 1.25;
              targetAlpha = 1;
            } else {
              targetScale = 0.9;
              targetAlpha = 0.3;
            }
          }

          gsap.to(el, {
            y: 0,
            x: 0,
            scale: targetScale,
            autoAlpha: targetAlpha,
            duration: 0.4,
            ease: 'power2.out',
            overwrite: true
          });
        }
      });
    }, containerRef);
    return () => ctx.revert();
  }, [clickedProject, hoveredIndex, isAnimating]);

  // 3. Image/video scaling logic (Switched to useLayoutEffect for smoother swap)
  useLayoutEffect(() => {
    if (!displayedProject || !imageRef.current) return;

    const vh = window.innerHeight;
    const vw = window.innerWidth;
    const baseHeight = imageRef.current.offsetHeight || (vh * 0.5);
    const targetScale = (vh * 0.65) / baseHeight;
    const targetX = vw * 0.08;
    const targetY = -vh * 0.07;

    if (clickedProject) {
      wasClicked.current = true;

      gsap.to(imageRef.current, {
        scale: targetScale,
        x: targetX,
        y: targetY,
        autoAlpha: 1,
        duration: 0.6,
        ease: 'power3.out',
        onComplete: () => setIsVideo(true),
      });

    } else {

      if (wasClicked.current) {
        wasClicked.current = false;

        gsap.fromTo(imageRef.current,
          {
            scale: targetScale,
            x: targetX,
            y: targetY,
            autoAlpha: 1
          },
          {
            scale: 1,
            x: 0,
            y: 0,
            duration: 0.5,
            ease: 'power3.out'
          }
        );

      } else {
        gsap.fromTo(imageRef.current,
          {
            autoAlpha: 0,
            scale: 0.95,
            x: 0,
            y: 0
          },
          {
            autoAlpha: 1,
            scale: 1,
            x: 0,
            y: 0,
            duration: 0.4,
            ease: 'power2.out',
            overwrite: 'auto'
          }
        );
      }
    }
  }, [clickedProject, displayedProject]);

  // 4. Video Sync
  useEffect(() => {
    if (isVideo && videoRef.current && imageRef.current) {
      const vh = window.innerHeight;
      const vw = window.innerWidth;
      const baseHeight = imageRef.current.offsetHeight;
      const targetScale = (vh * 0.65) / baseHeight;

      gsap.set(videoRef.current, {
        scale: targetScale,
        x: vw * 0.08,
        y: -vh * 0.07,
      });
    } else if (!isVideo && imageRef.current) {
      gsap.set(imageRef.current, { opacity: 1 });
    }
  }, [isVideo]);

  const handleBackOrClose = () => {
    if (clickedProject) {
      setActiveProject(clickedProject);
      setIsVideo(false);
      setClickedProject(null);
      setHoveredIndex(null);
      return;
    }

    const validTitles = titleRefs.current.filter(Boolean);
    const reversedTitles = [...validTitles].reverse();

    const tl = gsap.timeline({
      onComplete: onClose,
    });

    tl.to(reversedTitles, {
      x: 100,
      autoAlpha: 0,
      duration: 0.6,
      stagger: 0.08,
      ease: "power3.in",
    });

    tl.to(
      closeBtnRef.current,
      {
        autoAlpha: 0,
        duration: 0.2,
      },
      "<"
    );
  };

  return (
    <div ref={containerRef} className="relative w-full h-full flex font-robotoCondensed">
      <button ref={closeBtnRef} onClick={handleBackOrClose} className="absolute right-4 top-4 z-50 text-xl p-2 cursor-pointer">
        {clickedProject ? <span className="inline-block [transform:scale(1.5)]">﹤</span> : '✕'}
      </button>

      {/* Left Side (Media) */}
      <div className="w-1/2 flex flex-col items-center justify-center pointer-events-none relative">
        {displayedProject && (
          <>
            <img ref={imageRef} key={displayedProject.title} src={displayedProject.image}
              className="max-w-[80%] max-h-[70%] object-contain rounded-md absolute z-10"
              alt={displayedProject.title}
              width="1918"
              height="1078"
              loading="lazy"
              decoding="async"
            />
            {isVideo && (
              <video
                ref={videoRef}
                src={projectVideos[displayedProject.title]}
                poster={displayedProject.image}
                className="max-w-[80%] max-h-[70%] object-contain rounded-md absolute z-20"
                autoPlay
                muted
                loop
                playsInline
                preload="metadata"
                style={{ opacity: 0 }}
                onPlaying={() => {
                  gsap.set(videoRef.current, { opacity: 1 });
                  gsap.set(imageRef.current, { opacity: 0 });
                }}
              />
            )}
          </>
        )}
      </div>

      {/* Description */}
      {clickedProject && (
        <p className="absolute right-0 top-1/2 -translate-y-[100%] -translate-x-5 mt-4 text-left text-[2.5vh] max-w-[57vh] animate-fade-scale">
          {clickedProject.description}
        </p>
      )}

      {/* Right Side (List) */}
      <div className="w-1/2 h-full">
        <section className={`h-full flex flex-col items-end justify-center px-16 ${isAnimating ? 'pointer-events-none' : ''}`}>
          {projects.map((project, index) => {
            const isSelected = clickedProject?.title === project.title;

            return (
              <h3 key={project.title} ref={(el) => (titleRefs.current[index] = el)}
                className="project-title font-light whitespace-nowrap cursor-pointer opacity-0 invisible origin-right relative z-[100]"
                onMouseEnter={() => {
                  if (!clickedProject) {
                    const img = new Image();
                    img.decoding = 'async';
                    img.src = project.image;
                    setHoveredIndex(index);
                    setActiveProject(project);
                  }
                }}
                onMouseLeave={() => !clickedProject && (setHoveredIndex(null), setActiveProject(null))}
                onClick={() => {
                  if (isSelected) {
                    if (project.url) window.open(project.url, '_blank');
                  } else {
                    setClickedProject(project);
                  }
                }}
              >
                {project.title}

                {isSelected && (
                  <span style={{ fontSize: '2vh', transform: 'translate(-0.5vh, -6vh)', display: 'inline-block'
                    }}>↗</span>
                )}
              </h3>
            );
          })}
        </section>
      </div>
    </div>
  );
};

export default ProjectsPopup;
